import{c as t,Q as n,j as l,m as e}from"./chunks/framework.DOi4mjdC.js";const s="/assets/GEMV%E6%A8%A1%E5%BC%8FM-1%E7%9A%84%E7%9F%A9%E9%98%B5%E4%B9%98%E8%AE%A1%E7%AE%97%E7%A4%BA%E6%84%8F%E5%9B%BE.DLIlrNu4.png",i="/assets/%E9%9D%9EGEMV%E6%A8%A1%E5%BC%8FM-1%E7%9A%84%E7%9F%A9%E9%98%B5%E4%B9%98%E8%AE%A1%E7%AE%97%E7%A4%BA%E6%84%8F%E5%9B%BE.DJ3IVVnt.png",_=JSON.parse('{"title":"矩阵向量乘","description":"","frontmatter":{},"headers":[{"level":1,"title":"矩阵向量乘","slug":"矩阵向量乘"},{"level":2,"title":"功能介绍","slug":"功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/矩阵向量乘.md","filePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/矩阵向量乘.md"}'),p={name:"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/矩阵向量乘.md"};function o(r,a,m,c,u,d){return n(),l("div",null,[...a[0]||(a[0]=[e('<h1 id="矩阵向量乘" tabindex="-1">矩阵向量乘 <a class="header-anchor" href="#矩阵向量乘" aria-label="Permalink to &quot;矩阵向量乘&quot;">​</a></h1><h2 id="功能介绍" tabindex="-1">功能介绍 <a class="header-anchor" href="#功能介绍" aria-label="Permalink to &quot;功能介绍&quot;">​</a></h2><p>矩阵向量乘（General Matrix-Vector multiplication），即GEMV，是指Matmul计算中M=1，形状为(1, K)的左矩阵A与形状为(K, N)的右矩阵B进行矩阵乘运算的场景。Matmul支持在Tiling侧与Kernel侧通过配置A矩阵的数据格式为<a href="./../../../../编程指南/概念原理和术语/神经网络和算子/数据排布格式.html#li51557161818">VECTOR</a>来开启GEMV模式，从而高效处理M=1的计算场景。若在M=1时未开启GEMV模式，Matmul计算则将M方向作为非对齐场景进行处理。GEMV模式相较于非对齐处理方式，搬运数据量更少，性能更好。</p><p>以M=1，K=256，N=32，左右矩阵数据类型为half的Matmul为具体示例，说明GEMV模式的Matmul API内部处理过程。</p><ul><li><p>GEMV模式</p><p>将A矩阵从A1搬运到A2时，1*256的向量被当作16*16的矩阵进行处理，调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/LoadData.md" target="_blank" rel="noreferrer">LoadData</a>接口一次完成16*16分形大小的矩阵搬运。B矩阵的搬运以及矩阵乘计算跟基础场景相同，如下图所示。</p><p><strong>图 1</strong> GEMV模式M=1的矩阵乘计算示意图<br><img src="'+s+'" alt="" title="GEMV模式M-1的矩阵乘计算示意图"></p></li><li><p>非GEMV模式</p><p>将A矩阵从A1搬运到A2时，1*256的向量被当作非对齐矩阵数据进行处理，将M方向对齐到32字节后进行搬运。调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/LoadData.md" target="_blank" rel="noreferrer">LoadData</a>接口每次搬运16*16分形大小的矩阵，一共搬运K/16=16次，导致搬运数据量增加，性能相较于GEMV模式差，如下图所示。</p><p><strong>图 2</strong> 非GEMV模式M=1的矩阵乘计算示意图<br><img src="'+i+`" alt="" title="非GEMV模式M-1的矩阵乘计算示意图"></p></li></ul><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><p>形状为(1, K)的A矩阵（M=1，K&gt;1）做矩阵乘计算，即输入A矩阵的数据是向量数据。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>在Matmul计算中，若要开启GEMV模式，A矩阵的原始输入形状M必须等于1。</p></li><li><p>GEMV场景下，左矩阵A不支持转置。</p></li><li><p>GEMV场景下，Global Memory上的左矩阵数据需要保证16字节对齐。</p></li><li><p><a href="./MxMatmul场景.html">MxMatmul场景</a>计算矩阵向量乘时，左矩阵A和左量化系数矩阵scaleA仅支持内存逻辑位置为TPosition::GM。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整的算子样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_format_gemv" target="_blank" rel="noreferrer">matmul_gemv算子样例</a>。</p><ul><li><p>Tiling实现</p><p>调用SetAType接口，设置A矩阵的数据格式为CubeFormat::VECTOR，其它Tiling实现与<a href="./../算子实现.html#zh-cn_topic_0000001622514006_li19113114819525">基础场景</a>相同。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());</span></span>
<span class="line"><span>matmul_tiling::MatmulApiTiling tiling(ascendcPlatform);</span></span>
<span class="line"><span>// 调用设置A矩阵的格式为CubeFormat::VECTOR</span></span>
<span class="line"><span>tiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::VECTOR, matmul_tiling::DataType::DT_FLOAT16);</span></span>
<span class="line"><span>tiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16); </span></span>
<span class="line"><span>tiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);</span></span>
<span class="line"><span>tiling.SetBiasType(AscendC::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT); </span></span>
<span class="line"><span>... // 其他实现内容</span></span>
<span class="line"><span>optiling::TCubeTiling tilingData;   </span></span>
<span class="line"><span>int ret = tiling.GetTiling(tilingData);</span></span></code></pre></div></li><li><p>Kernel实现</p><p>相较于<a href="./../算子实现.html#zh-cn_topic_0000001622514006_li1032116474330">基础场景</a>，GEMV场景在创建Matmul对象时，设置模板参数A_TYPE的数据格式为CubeFormat::VECTOR。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;lib/matmul_intf.h&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using A_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::VECTOR, half&gt;; </span></span>
<span class="line"><span>using B_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt;;</span></span>
<span class="line"><span>using C_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt;; </span></span>
<span class="line"><span>using BIAS_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt;; </span></span>
<span class="line"><span>AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE&gt; mm;</span></span></code></pre></div></li></ul>`,12)])])}const E=t(p,[["render",o]]);export{_ as __pageData,E as default};
